css:
.sec{display:grid; grid-template-columns:230px 1fr; gap:0}
.sec>h2{position:sticky; top:120px; align-self:start;
  writing-mode:vertical-rl; letter-spacing:.18em; margin:0}
.sec>.list{border:0}            /* 罫は引かない */
/* パネルの外へ見出しを出す場合 */
.sec--panel{display:grid; grid-template-columns:38% 62%}
.sec--panel>h2{grid-column:2; text-align:left; margin:0 0 14px}
.sec--panel>.num{grid-column:1; grid-row:1/3}
